#!/bin/bash
# probe.sh <name> <ext> <args...>  ; source read from stdin
name="$1"; ext="$2"; shift 2
d=/tmp/probe/work-checks-core-error
cat > "$d/$name.$ext"
echo "##### CASE $name.$ext  ARGS: [$*]"
echo "--- SOURCE:"
cat -n "$d/$name.$ext"
( cd "$d" && /workspace/executable "$@" "$name.$ext" > "$d/.o" 2> "$d/.e" ; echo "exit=$?" > "$d/.x" )
echo "--- exit: $(cat $d/.x)"
echo "--- STDOUT:"; cat "$d/.o"
echo "--- STDERR:"; cat "$d/.e"
echo "##### END $name"
SH
chmod +x probe.sh
